#include <WiFi.h>
#include <WebServer.h>
#include "secrets.h"
#include "index.h"

WebServer server(80);

void handleRoot() {
  server.send(200, "text/html", INDEX_HTML);
}

void setup() {
  Serial.begin(115200);
  WiFi.begin(SECRET_SSID, SECRET_PASS);
  Serial.print("Connecting");

  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }

  Serial.println();
  Serial.print("Open http://");
  Serial.println(WiFi.localIP());

  server.on("/", handleRoot);
  server.begin();
}

void loop() {
  server.handleClient();
}
